mkitem!{declare_lint ! { # [doc = " The `forbidden_lint_groups` lint detects violations of"] # [doc = " `forbid` applied to a lint group. Due to a bug in the compiler,"] # [doc = " these used to be overlooked entirely. They now generate a warning."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![forbid(warnings)]"] # [doc = " #![warn(bad_style)]"] # [doc = ""] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Recommended fix"] # [doc = ""] # [doc = " If your crate is using `#![forbid(warnings)]`,"] # [doc = " we recommend that you change to `#![deny(warnings)]`."] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Due to a compiler bug, applying `forbid` to lint groups"] # [doc = " previously had no effect. The bug is now fixed but instead of"] # [doc = " enforcing `forbid` we issue this future-compatibility warning"] # [doc = " to avoid breaking existing crates."] pub FORBIDDEN_LINT_GROUPS , Warn , "applying forbid to lint-groups" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #81670 <https://github.com/rust-lang/rust/issues/81670>" , report_in_deps : true , } ; }}
mkitem!{declare_lint ! { # [doc = " The `ill_formed_attribute_input` lint detects ill-formed attribute"] # [doc = " inputs that were previously accepted and used in practice."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #[inline = \"this is not valid\"]"] # [doc = " fn foo() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Previously, inputs for many built-in attributes weren't validated and"] # [doc = " nonsensical attribute inputs were accepted. After validation was"] # [doc = " added, it was determined that some existing projects made use of these"] # [doc = " invalid forms. This is a [future-incompatible] lint to transition this"] # [doc = " to a hard error in the future. See [issue #57571] for more details."] # [doc = ""] # [doc = " Check the [attribute reference] for details on the valid inputs for"] # [doc = " attributes."] # [doc = ""] # [doc = " [issue #57571]: https://github.com/rust-lang/rust/issues/57571"] # [doc = " [attribute reference]: https://doc.rust-lang.org/nightly/reference/attributes.html"] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub ILL_FORMED_ATTRIBUTE_INPUT , Deny , "ill-formed attribute inputs that were previously accepted and used in practice" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #57571 <https://github.com/rust-lang/rust/issues/57571>" , report_in_deps : true , } ; crate_level_only }}
