mkitem!{declare_lint ! { # [doc = " The `meta_variable_misuse` lint detects possible meta-variable misuse"] # [doc = " in macro definitions."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(meta_variable_misuse)]"] # [doc = ""] # [doc = " macro_rules! foo {"] # [doc = "     () => {};"] # [doc = "     ($( $i:ident = $($j:ident),+ );*) => { $( $( $i = $k; )+ )* };"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     foo!();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " There are quite a few different ways a [`macro_rules`] macro can be"] # [doc = " improperly defined. Many of these errors were previously only detected"] # [doc = " when the macro was expanded or not at all. This lint is an attempt to"] # [doc = " catch some of these problems when the macro is *defined*."] # [doc = ""] # [doc = " This lint is \"allow\" by default because it may have false positives"] # [doc = " and other issues. See [issue #61053] for more details."] # [doc = ""] # [doc = " [`macro_rules`]: https://doc.rust-lang.org/reference/macros-by-example.html"] # [doc = " [issue #61053]: https://github.com/rust-lang/rust/issues/61053"] pub META_VARIABLE_MISUSE , Allow , "possible meta-variable misuse at macro definition" }}
mkitem!{declare_lint ! { # [doc = " The `incomplete_include` lint detects the use of the [`include!`]"] # [doc = " macro with a file that contains more than one expression."] # [doc = ""] # [doc = " [`include!`]: https://doc.rust-lang.org/std/macro.include.html"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs separate file)"] # [doc = " fn main() {"] # [doc = "     include!(\"foo.txt\");"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " where the file `foo.txt` contains:"] # [doc = ""] # [doc = " ```text"] # [doc = " println!(\"hi!\");"] # [doc = " ```"] # [doc = ""] # [doc = " produces:"] # [doc = ""] # [doc = " ```text"] # [doc = " error: include macro expected single expression in source"] # [doc = "  --> foo.txt:1:14"] # [doc = "   |"] # [doc = " 1 | println!(\"1\");"] # [doc = "   |              ^"] # [doc = "   |"] # [doc = "   = note: `#[deny(incomplete_include)]` on by default"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The [`include!`] macro is currently only intended to be used to"] # [doc = " include a single [expression] or multiple [items]. Historically it"] # [doc = " would ignore any contents after the first expression, but that can be"] # [doc = " confusing. In the example above, the `println!` expression ends just"] # [doc = " before the semicolon, making the semicolon \"extra\" information that is"] # [doc = " ignored. Perhaps even more surprising, if the included file had"] # [doc = " multiple print statements, the subsequent ones would be ignored!"] # [doc = ""] # [doc = " One workaround is to place the contents in braces to create a [block"] # [doc = " expression]. Also consider alternatives, like using functions to"] # [doc = " encapsulate the expressions, or use [proc-macros]."] # [doc = ""] # [doc = " This is a lint instead of a hard error because existing projects were"] # [doc = " found to hit this error. To be cautious, it is a lint for now. The"] # [doc = " future semantics of the `include!` macro are also uncertain, see"] # [doc = " [issue #35560]."] # [doc = ""] # [doc = " [items]: https://doc.rust-lang.org/reference/items.html"] # [doc = " [expression]: https://doc.rust-lang.org/reference/expressions.html"] # [doc = " [block expression]: https://doc.rust-lang.org/reference/expressions/block-expr.html"] # [doc = " [proc-macros]: https://doc.rust-lang.org/reference/procedural-macros.html"] # [doc = " [issue #35560]: https://github.com/rust-lang/rust/issues/35560"] pub INCOMPLETE_INCLUDE , Deny , "trailing content in included file" }}
mkitem!{declare_lint ! { # [doc = " The `arithmetic_overflow` lint detects that an arithmetic operation"] # [doc = " will [overflow]."] # [doc = ""] # [doc = " [overflow]: https://doc.rust-lang.org/reference/expressions/operator-expr.html#overflow"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " 1_i32 << 32;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " It is very likely a mistake to perform an arithmetic operation that"] # [doc = " overflows its value. If the compiler is able to detect these kinds of"] # [doc = " overflows at compile-time, it will trigger this lint. Consider"] # [doc = " adjusting the expression to avoid overflow, or use a data type that"] # [doc = " will not overflow."] pub ARITHMETIC_OVERFLOW , Deny , "arithmetic operation overflows" , @ eval_always = true }}
