mkitem!{declare_lint ! { # [doc = " The `must_not_suspend` lint guards against values that shouldn't be held across suspend points"] # [doc = " (`.await`)"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(must_not_suspend)]"] # [doc = " #![warn(must_not_suspend)]"] # [doc = ""] # [doc = " #[must_not_suspend]"] # [doc = " struct SyncThing {}"] # [doc = ""] # [doc = " async fn yield_now() {}"] # [doc = ""] # [doc = " pub async fn uhoh() {"] # [doc = "     let guard = SyncThing {};"] # [doc = "     yield_now().await;"] # [doc = "     let _guard = guard;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The `must_not_suspend` lint detects values that are marked with the `#[must_not_suspend]`"] # [doc = " attribute being held across suspend points. A \"suspend\" point is usually a `.await` in an async"] # [doc = " function."] # [doc = ""] # [doc = " This attribute can be used to mark values that are semantically incorrect across suspends"] # [doc = " (like certain types of timers), values that have async alternatives, and values that"] # [doc = " regularly cause problems with the `Send`-ness of async fn's returned futures (like"] # [doc = " `MutexGuard`'s)"] # [doc = ""] pub MUST_NOT_SUSPEND , Allow , "use of a `#[must_not_suspend]` value across a yield point" , @ feature_gate = must_not_suspend ; }}
mkitem!{declare_lint ! { # [doc = " The `unused_extern_crates` lint guards against `extern crate` items"] # [doc = " that are never used."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(unused_extern_crates)]"] # [doc = " #![deny(warnings)]"] # [doc = " extern crate proc_macro;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " `extern crate` items that are unused have no effect and should be"] # [doc = " removed. Note that there are some cases where specifying an `extern"] # [doc = " crate` is desired for the side effect of ensuring the given crate is"] # [doc = " linked, even though it is not otherwise directly referenced. The lint"] # [doc = " can be silenced by aliasing the crate to an underscore, such as"] # [doc = " `extern crate foo as _`. Also note that it is no longer idiomatic to"] # [doc = " use `extern crate` in the [2018 edition], as extern crates are now"] # [doc = " automatically added in scope."] # [doc = ""] # [doc = " This lint is \"allow\" by default because it can be noisy, and produce"] # [doc = " false-positives. If a dependency is being removed from a project, it"] # [doc = " is recommended to remove it from the build configuration (such as"] # [doc = " `Cargo.toml`) to ensure stale build entries aren't left behind."] # [doc = ""] # [doc = " [2018 edition]: https://doc.rust-lang.org/edition-guide/rust-2018/module-system/path-clarity.html#no-more-extern-crate"] pub UNUSED_EXTERN_CRATES , Allow , "extern crates that are never used" }}
