mkitem!{declare_lint ! { # [doc = " The `unused_assignments` lint detects assignments that will never be read."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " let mut x = 5;"] # [doc = " x = 6;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Unused assignments may signal a mistake or unfinished code. If the"] # [doc = " variable is never used after being assigned, then the assignment can"] # [doc = " be removed. Variables with an underscore prefix such as `_x` will not"] # [doc = " trigger this lint."] pub UNUSED_ASSIGNMENTS , Warn , "detect assignments that will never be read" }}
mkitem!{declare_lint ! { # [doc = " The `dead_code` lint detects unused, unexported items."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn foo() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Dead code may signal a mistake or unfinished code. To silence the"] # [doc = " warning for individual items, prefix the name with an underscore such"] # [doc = " as `_foo`. If it was intended to expose the item outside of the crate,"] # [doc = " consider adding a visibility modifier like `pub`."] # [doc = ""] # [doc = " To preserve the numbering of tuple structs with unused fields,"] # [doc = " change the unused fields to have unit type or use"] # [doc = " `PhantomData`."] # [doc = ""] # [doc = " Otherwise consider removing the unused code."] # [doc = ""] # [doc = " ### Limitations"] # [doc = ""] # [doc = " Removing fields that are only used for side-effects and never"] # [doc = " read will result in behavioral changes. Examples of this"] # [doc = " include:"] # [doc = ""] # [doc = " - If a field's value performs an action when it is dropped."] # [doc = " - If a field's type does not implement an auto trait"] # [doc = "   (e.g. `Send`, `Sync`, `Unpin`)."] # [doc = ""] # [doc = " For side-effects from dropping field values, this lint should"] # [doc = " be allowed on those fields. For side-effects from containing"] # [doc = " field types, `PhantomData` should be used."] pub DEAD_CODE , Warn , "detect unused, unexported items" }}
mkitem!{declare_lint ! { # [doc = " The `unused_attributes` lint detects attributes that were not used by"] # [doc = " the compiler."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![ignore]"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Unused [attributes] may indicate the attribute is placed in the wrong"] # [doc = " position. Consider removing it, or placing it in the correct position."] # [doc = " Also consider if you intended to use an _inner attribute_ (with a `!`"] # [doc = " such as `#![allow(unused)]`) which applies to the item the attribute"] # [doc = " is within, or an _outer attribute_ (without a `!` such as"] # [doc = " `#[allow(unused)]`) which applies to the item *following* the"] # [doc = " attribute."] # [doc = ""] # [doc = " [attributes]: https://doc.rust-lang.org/reference/attributes.html"] pub UNUSED_ATTRIBUTES , Warn , "detects attributes that were not used by the compiler" }}
mkitem!{declare_lint ! { # [doc = " The `unreachable_code` lint detects unreachable code paths."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " panic!(\"we never go past here!\");"] # [doc = ""] # [doc = " let x = 5;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Unreachable code may signal a mistake or unfinished code. If the code"] # [doc = " is no longer in use, consider removing it."] pub UNREACHABLE_CODE , Warn , "detects unreachable code paths" , report_in_external_macro }}
mkitem!{declare_lint ! { # [doc = " The `unreachable_patterns` lint detects unreachable patterns."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " let x = 5;"] # [doc = " match x {"] # [doc = "     y => (),"] # [doc = "     5 => (),"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " This usually indicates a mistake in how the patterns are specified or"] # [doc = " ordered. In this example, the `y` pattern will always match, so the"] # [doc = " five is impossible to reach. Remember, match arms match in order, you"] # [doc = " probably wanted to put the `5` case above the `y` case."] pub UNREACHABLE_PATTERNS , Warn , "detects unreachable patterns" }}
mkitem!{declare_lint ! { # [doc = " The `overlapping_range_endpoints` lint detects `match` arms that have [range patterns] that"] # [doc = " overlap on their endpoints."] # [doc = ""] # [doc = " [range patterns]: https://doc.rust-lang.org/nightly/reference/patterns.html#range-patterns"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " let x = 123u8;"] # [doc = " match x {"] # [doc = "     0..=100 => { println!(\"small\"); }"] # [doc = "     100..=255 => { println!(\"large\"); }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " It is likely a mistake to have range patterns in a match expression that overlap in this"] # [doc = " way. Check that the beginning and end values are what you expect, and keep in mind that"] # [doc = " with `..=` the left and right bounds are inclusive."] pub OVERLAPPING_RANGE_ENDPOINTS , Warn , "detects range patterns with overlapping endpoints" }}
mkitem!{declare_lint ! { # [doc = " The `non_contiguous_range_endpoints` lint detects likely off-by-one errors when using"] # [doc = " exclusive [range patterns]."] # [doc = ""] # [doc = " [range patterns]: https://doc.rust-lang.org/nightly/reference/patterns.html#range-patterns"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " let x = 123u32;"] # [doc = " match x {"] # [doc = "     0..100 => { println!(\"small\"); }"] # [doc = "     101..1000 => { println!(\"large\"); }"] # [doc = "     _ => { println!(\"larger\"); }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " It is likely a mistake to have range patterns in a match expression that miss out a single"] # [doc = " number. Check that the beginning and end values are what you expect, and keep in mind that"] # [doc = " with `..=` the right bound is inclusive, and with `..` it is exclusive."] pub NON_CONTIGUOUS_RANGE_ENDPOINTS , Warn , "detects off-by-one errors with exclusive range patterns" }}
mkitem!{declare_lint ! { # [doc = " The `bindings_with_variant_name` lint detects pattern bindings with"] # [doc = " the same name as one of the matched variants."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " pub enum Enum {"] # [doc = "     Foo,"] # [doc = "     Bar,"] # [doc = " }"] # [doc = ""] # [doc = " pub fn foo(x: Enum) {"] # [doc = "     match x {"] # [doc = "         Foo => {}"] # [doc = "         Bar => {}"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " It is usually a mistake to specify an enum variant name as an"] # [doc = " [identifier pattern]. In the example above, the `match` arms are"] # [doc = " specifying a variable name to bind the value of `x` to. The second arm"] # [doc = " is ignored because the first one matches *all* values. The likely"] # [doc = " intent is that the arm was intended to match on the enum variant."] # [doc = ""] # [doc = " Two possible solutions are:"] # [doc = ""] # [doc = " * Specify the enum variant using a [path pattern], such as"] # [doc = "   `Enum::Foo`."] # [doc = " * Bring the enum variants into local scope, such as adding `use"] # [doc = "   Enum::*;` to the beginning of the `foo` function in the example"] # [doc = "   above."] # [doc = ""] # [doc = " [identifier pattern]: https://doc.rust-lang.org/reference/patterns.html#identifier-patterns"] # [doc = " [path pattern]: https://doc.rust-lang.org/reference/patterns.html#path-patterns"] pub BINDINGS_WITH_VARIANT_NAME , Deny , "detects pattern bindings with the same name as one of the matched variants" }}
mkitem!{declare_lint ! { # [doc = " The `unused_macros` lint detects macros that were not used."] # [doc = ""] # [doc = " Note that this lint is distinct from the `unused_macro_rules` lint,"] # [doc = " which checks for single rules that never match of an otherwise used"] # [doc = " macro, and thus never expand."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " macro_rules! unused {"] # [doc = "     () => {};"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Unused macros may signal a mistake or unfinished code. To silence the"] # [doc = " warning for the individual macro, prefix the name with an underscore"] # [doc = " such as `_my_macro`. If you intended to export the macro to make it"] # [doc = " available outside of the crate, use the [`macro_export` attribute]."] # [doc = ""] # [doc = " [`macro_export` attribute]: https://doc.rust-lang.org/reference/macros-by-example.html#path-based-scope"] pub UNUSED_MACROS , Warn , "detects macros that were not used" }}
mkitem!{declare_lint ! { # [doc = " The `unused_macro_rules` lint detects macro rules that were not used."] # [doc = ""] # [doc = " Note that the lint is distinct from the `unused_macros` lint, which"] # [doc = " fires if the entire macro is never called, while this lint fires for"] # [doc = " single unused rules of the macro that is otherwise used."] # [doc = " `unused_macro_rules` fires only if `unused_macros` wouldn't fire."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #[warn(unused_macro_rules)]"] # [doc = " macro_rules! unused_empty {"] # [doc = "     (hello) => { println!(\"Hello, world!\") }; // This rule is unused"] # [doc = "     () => { println!(\"empty\") }; // This rule is used"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     unused_empty!(hello);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Unused macro rules may signal a mistake or unfinished code. Furthermore,"] # [doc = " they slow down compilation. Right now, silencing the warning is not"] # [doc = " supported on a single rule level, so you have to add an allow to the"] # [doc = " entire macro definition."] # [doc = ""] # [doc = " If you intended to export the macro to make it"] # [doc = " available outside of the crate, use the [`macro_export` attribute]."] # [doc = ""] # [doc = " [`macro_export` attribute]: https://doc.rust-lang.org/reference/macros-by-example.html#path-based-scope"] pub UNUSED_MACRO_RULES , Allow , "detects macro rules that were not used" }}
mkitem!{declare_lint ! { # [doc = " The `warnings` lint allows you to change the level of other"] # [doc = " lints which produce warnings."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![deny(warnings)]"] # [doc = " fn foo() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The `warnings` lint is a bit special; by changing its level, you"] # [doc = " change every other warning that would produce a warning to whatever"] # [doc = " value you'd like. As such, you won't ever trigger this lint in your"] # [doc = " code directly."] pub WARNINGS , Warn , "mass-change the level for lints which produce warnings" }}
mkitem!{declare_lint ! { # [doc = " The `unused_features` lint detects unused or unknown features found in"] # [doc = " crate-level [`feature` attributes]."] # [doc = ""] # [doc = " [`feature` attributes]: https://doc.rust-lang.org/nightly/unstable-book/"] # [doc = ""] # [doc = " Note: This lint is currently not functional, see [issue #44232] for"] # [doc = " more details."] # [doc = ""] # [doc = " [issue #44232]: https://github.com/rust-lang/rust/issues/44232"] pub UNUSED_FEATURES , Warn , "unused features found in crate-level `#[feature]` directives" }}
mkitem!{declare_lint ! { # [doc = " The `stable_features` lint detects a [`feature` attribute] that"] # [doc = " has since been made stable."] # [doc = ""] # [doc = " [`feature` attribute]: https://doc.rust-lang.org/nightly/unstable-book/"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(test_accepted_feature)]"] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " When a feature is stabilized, it is no longer necessary to include a"] # [doc = " `#![feature]` attribute for it. To fix, simply remove the"] # [doc = " `#![feature]` attribute."] pub STABLE_FEATURES , Warn , "stable features found in `#[feature]` directive" }}
mkitem!{declare_lint ! { # [doc = " The `unknown_crate_types` lint detects an unknown crate type found in"] # [doc = " a [`crate_type` attribute]."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![crate_type=\"lol\"]"] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " An unknown value give to the `crate_type` attribute is almost"] # [doc = " certainly a mistake."] # [doc = ""] # [doc = " [`crate_type` attribute]: https://doc.rust-lang.org/reference/linkage.html"] pub UNKNOWN_CRATE_TYPES , Deny , "unknown crate type found in `#[crate_type]` directive" , crate_level_only }}
mkitem!{declare_lint ! { # [doc = " The `trivial_casts` lint detects trivial casts which could be replaced"] # [doc = " with coercion, which may require a temporary variable."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(trivial_casts)]"] # [doc = " let x: &u32 = &42;"] # [doc = " let y = x as *const u32;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " A trivial cast is a cast `e as T` where `e` has type `U` and `U` is a"] # [doc = " subtype of `T`. This type of cast is usually unnecessary, as it can be"] # [doc = " usually be inferred."] # [doc = ""] # [doc = " This lint is \"allow\" by default because there are situations, such as"] # [doc = " with FFI interfaces or complex type aliases, where it triggers"] # [doc = " incorrectly, or in situations where it will be more difficult to"] # [doc = " clearly express the intent. It may be possible that this will become a"] # [doc = " warning in the future, possibly with an explicit syntax for coercions"] # [doc = " providing a convenient way to work around the current issues."] # [doc = " See [RFC 401 (coercions)][rfc-401], [RFC 803 (type ascription)][rfc-803] and"] # [doc = " [RFC 3307 (remove type ascription)][rfc-3307] for historical context."] # [doc = ""] # [doc = " [rfc-401]: https://github.com/rust-lang/rfcs/blob/master/text/0401-coercions.md"] # [doc = " [rfc-803]: https://github.com/rust-lang/rfcs/blob/master/text/0803-type-ascription.md"] # [doc = " [rfc-3307]: https://github.com/rust-lang/rfcs/blob/master/text/3307-de-rfc-type-ascription.md"] pub TRIVIAL_CASTS , Allow , "detects trivial casts which could be removed" }}
mkitem!{declare_lint ! { # [doc = " The `trivial_numeric_casts` lint detects trivial numeric casts of types"] # [doc = " which could be removed."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(trivial_numeric_casts)]"] # [doc = " let x = 42_i32 as i32;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " A trivial numeric cast is a cast of a numeric type to the same numeric"] # [doc = " type. This type of cast is usually unnecessary."] # [doc = ""] # [doc = " This lint is \"allow\" by default because there are situations, such as"] # [doc = " with FFI interfaces or complex type aliases, where it triggers"] # [doc = " incorrectly, or in situations where it will be more difficult to"] # [doc = " clearly express the intent. It may be possible that this will become a"] # [doc = " warning in the future, possibly with an explicit syntax for coercions"] # [doc = " providing a convenient way to work around the current issues."] # [doc = " See [RFC 401 (coercions)][rfc-401], [RFC 803 (type ascription)][rfc-803] and"] # [doc = " [RFC 3307 (remove type ascription)][rfc-3307] for historical context."] # [doc = ""] # [doc = " [rfc-401]: https://github.com/rust-lang/rfcs/blob/master/text/0401-coercions.md"] # [doc = " [rfc-803]: https://github.com/rust-lang/rfcs/blob/master/text/0803-type-ascription.md"] # [doc = " [rfc-3307]: https://github.com/rust-lang/rfcs/blob/master/text/3307-de-rfc-type-ascription.md"] pub TRIVIAL_NUMERIC_CASTS , Allow , "detects trivial casts of numeric types which could be removed" }}
mkitem!{declare_lint ! { # [doc = " The `exported_private_dependencies` lint detects private dependencies"] # [doc = " that are exposed in a public interface."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs-dependency)"] # [doc = " pub fn foo() -> Option<some_private_dependency::Thing> {"] # [doc = "     None"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: type `bar::Thing` from private dependency 'bar' in public interface"] # [doc = "  --> src/lib.rs:3:1"] # [doc = "   |"] # [doc = " 3 | pub fn foo() -> Option<bar::Thing> {"] # [doc = "   | ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = "   |"] # [doc = "   = note: `#[warn(exported_private_dependencies)]` on by default"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Dependencies can be marked as \"private\" to indicate that they are not"] # [doc = " exposed in the public interface of a crate. This can be used by Cargo"] # [doc = " to independently resolve those dependencies because it can assume it"] # [doc = " does not need to unify them with other packages using that same"] # [doc = " dependency. This lint is an indication of a violation of that"] # [doc = " contract."] # [doc = ""] # [doc = " To fix this, avoid exposing the dependency in your public interface."] # [doc = " Or, switch the dependency to a public dependency."] # [doc = ""] # [doc = " Note that support for this is only available on the nightly channel."] # [doc = " See [RFC 1977] for more details, as well as the [Cargo documentation]."] # [doc = ""] # [doc = " [RFC 1977]: https://github.com/rust-lang/rfcs/blob/master/text/1977-public-private-dependencies.md"] # [doc = " [Cargo documentation]: https://doc.rust-lang.org/nightly/cargo/reference/unstable.html#public-dependency"] pub EXPORTED_PRIVATE_DEPENDENCIES , Warn , "public interface leaks type from a private dependency" }}
mkitem!{declare_lint ! { # [doc = " The `pub_use_of_private_extern_crate` lint detects a specific"] # [doc = " situation of re-exporting a private `extern crate`."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " extern crate core;"] # [doc = " pub use core as reexported_core;"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " A public `use` declaration should not be used to publically re-export a"] # [doc = " private `extern crate`. `pub extern crate` should be used instead."] # [doc = ""] # [doc = " This was historically allowed, but is not the intended behavior"] # [doc = " according to the visibility rules. This is a [future-incompatible]"] # [doc = " lint to transition this to a hard error in the future. See [issue"] # [doc = " #127909] for more details."] # [doc = ""] # [doc = " [issue #127909]: https://github.com/rust-lang/rust/issues/127909"] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub PUB_USE_OF_PRIVATE_EXTERN_CRATE , Deny , "detect public re-exports of private extern crates" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #127909 <https://github.com/rust-lang/rust/issues/127909>" , report_in_deps : true , } ; }}
mkitem!{declare_lint ! { # [doc = " The `invalid_type_param_default` lint detects type parameter defaults"] # [doc = " erroneously allowed in an invalid location."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " fn foo<T=i32>(t: T) {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Default type parameters were only intended to be allowed in certain"] # [doc = " situations, but historically the compiler allowed them everywhere."] # [doc = " This is a [future-incompatible] lint to transition this to a hard"] # [doc = " error in the future. See [issue #36887] for more details."] # [doc = ""] # [doc = " [issue #36887]: https://github.com/rust-lang/rust/issues/36887"] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub INVALID_TYPE_PARAM_DEFAULT , Deny , "type parameter default erroneously allowed in invalid location" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #36887 <https://github.com/rust-lang/rust/issues/36887>" , report_in_deps : true , } ; }}
mkitem!{declare_lint ! { # [doc = " The `renamed_and_removed_lints` lint detects lints that have been"] # [doc = " renamed or removed."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![deny(raw_pointer_derive)]"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " To fix this, either remove the lint or use the new name. This can help"] # [doc = " avoid confusion about lints that are no longer valid, and help"] # [doc = " maintain consistency for renamed lints."] pub RENAMED_AND_REMOVED_LINTS , Warn , "lints that have been renamed or removed" }}
mkitem!{declare_lint ! { # [doc = " The `const_item_mutation` lint detects attempts to mutate a `const`"] # [doc = " item."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " const FOO: [i32; 1] = [0];"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     FOO[0] = 1;"] # [doc = "     // This will print \"[0]\"."] # [doc = "     println!(\"{:?}\", FOO);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Trying to directly mutate a `const` item is almost always a mistake."] # [doc = " What is happening in the example above is that a temporary copy of the"] # [doc = " `const` is mutated, but the original `const` is not. Each time you"] # [doc = " refer to the `const` by name (such as `FOO` in the example above), a"] # [doc = " separate copy of the value is inlined at that location."] # [doc = ""] # [doc = " This lint checks for writing directly to a field (`FOO.field ="] # [doc = " some_value`) or array entry (`FOO[0] = val`), or taking a mutable"] # [doc = " reference to the const item (`&mut FOO`), including through an"] # [doc = " autoderef (`FOO.some_mut_self_method()`)."] # [doc = ""] # [doc = " There are various alternatives depending on what you are trying to"] # [doc = " accomplish:"] # [doc = ""] # [doc = " * First, always reconsider using mutable globals, as they can be"] # [doc = "   difficult to use correctly, and can make the code more difficult to"] # [doc = "   use or understand."] # [doc = " * If you are trying to perform a one-time initialization of a global:"] # [doc = "     * If the value can be computed at compile-time, consider using"] # [doc = "       const-compatible values (see [Constant Evaluation])."] # [doc = "     * For more complex single-initialization cases, consider using"] # [doc = "       [`std::sync::LazyLock`]."] # [doc = " * If you truly need a mutable global, consider using a [`static`],"] # [doc = "   which has a variety of options:"] # [doc = "   * Simple data types can be directly defined and mutated with an"] # [doc = "     [`atomic`] type."] # [doc = "   * More complex types can be placed in a synchronization primitive"] # [doc = "     like a [`Mutex`], which can be initialized with one of the options"] # [doc = "     listed above."] # [doc = "   * A [mutable `static`] is a low-level primitive, requiring unsafe."] # [doc = "     Typically This should be avoided in preference of something"] # [doc = "     higher-level like one of the above."] # [doc = ""] # [doc = " [Constant Evaluation]: https://doc.rust-lang.org/reference/const_eval.html"] # [doc = " [`static`]: https://doc.rust-lang.org/reference/items/static-items.html"] # [doc = " [mutable `static`]: https://doc.rust-lang.org/reference/items/static-items.html#mutable-statics"] # [doc = " [`std::sync::LazyLock`]: https://doc.rust-lang.org/stable/std/sync/struct.LazyLock.html"] # [doc = " [`atomic`]: https://doc.rust-lang.org/std/sync/atomic/index.html"] # [doc = " [`Mutex`]: https://doc.rust-lang.org/std/sync/struct.Mutex.html"] pub CONST_ITEM_MUTATION , Warn , "detects attempts to mutate a `const` item" , }}
mkitem!{declare_lint ! { # [doc = " The `patterns_in_fns_without_body` lint detects `mut` identifier"] # [doc = " patterns as a parameter in functions without a body."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " trait Trait {"] # [doc = "     fn foo(mut arg: u8);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " To fix this, remove `mut` from the parameter in the trait definition;"] # [doc = " it can be used in the implementation. That is, the following is OK:"] # [doc = ""] # [doc = " ```rust"] # [doc = " trait Trait {"] # [doc = "     fn foo(arg: u8); // Removed `mut` here"] # [doc = " }"] # [doc = ""] # [doc = " impl Trait for i32 {"] # [doc = "     fn foo(mut arg: u8) { // `mut` here is OK"] # [doc = ""] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Trait definitions can define functions without a body to specify a"] # [doc = " function that implementors must define. The parameter names in the"] # [doc = " body-less functions are only allowed to be `_` or an [identifier] for"] # [doc = " documentation purposes (only the type is relevant). Previous versions"] # [doc = " of the compiler erroneously allowed [identifier patterns] with the"] # [doc = " `mut` keyword, but this was not intended to be allowed. This is a"] # [doc = " [future-incompatible] lint to transition this to a hard error in the"] # [doc = " future. See [issue #35203] for more details."] # [doc = ""] # [doc = " [identifier]: https://doc.rust-lang.org/reference/identifiers.html"] # [doc = " [identifier patterns]: https://doc.rust-lang.org/reference/patterns.html#identifier-patterns"] # [doc = " [issue #35203]: https://github.com/rust-lang/rust/issues/35203"] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub PATTERNS_IN_FNS_WITHOUT_BODY , Deny , "patterns in functions without body were erroneously allowed" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #35203 <https://github.com/rust-lang/rust/issues/35203>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `late_bound_lifetime_arguments` lint detects generic lifetime"] # [doc = " arguments in path segments with late bound lifetime parameters."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " struct S;"] # [doc = ""] # [doc = " impl S {"] # [doc = "     fn late(self, _: &u8, _: &u8) {}"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     S.late::<'static>(&0, &0);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " It is not clear how to provide arguments for early-bound lifetime"] # [doc = " parameters if they are intermixed with late-bound parameters in the"] # [doc = " same list. For now, providing any explicit arguments will trigger this"] # [doc = " lint if late-bound parameters are present, so in the future a solution"] # [doc = " can be adopted without hitting backward compatibility issues. This is"] # [doc = " a [future-incompatible] lint to transition this to a hard error in the"] # [doc = " future. See [issue #42868] for more details, along with a description"] # [doc = " of the difference between early and late-bound parameters."] # [doc = ""] # [doc = " [issue #42868]: https://github.com/rust-lang/rust/issues/42868"] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub LATE_BOUND_LIFETIME_ARGUMENTS , Warn , "detects generic lifetime arguments in path segments with late bound lifetime parameters" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #42868 <https://github.com/rust-lang/rust/issues/42868>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `coherence_leak_check` lint detects conflicting implementations of"] # [doc = " a trait that are only distinguished by the old leak-check code."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " trait SomeTrait { }"] # [doc = " impl SomeTrait for for<'a> fn(&'a u8) { }"] # [doc = " impl<'a> SomeTrait for fn(&'a u8) { }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In the past, the compiler would accept trait implementations for"] # [doc = " identical functions that differed only in where the lifetime binder"] # [doc = " appeared. Due to a change in the borrow checker implementation to fix"] # [doc = " several bugs, this is no longer allowed. However, since this affects"] # [doc = " existing code, this is a [future-incompatible] lint to transition this"] # [doc = " to a hard error in the future."] # [doc = ""] # [doc = " Code relying on this pattern should introduce \"[newtypes]\","] # [doc = " like `struct Foo(for<'a> fn(&'a u8))`."] # [doc = ""] # [doc = " See [issue #56105] for more details."] # [doc = ""] # [doc = " [issue #56105]: https://github.com/rust-lang/rust/issues/56105"] # [doc = " [newtypes]: https://doc.rust-lang.org/book/ch19-04-advanced-types.html#using-the-newtype-pattern-for-type-safety-and-abstraction"] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub COHERENCE_LEAK_CHECK , Warn , "distinct impls distinguished only by the leak-check code" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: Custom ("the behavior may change in a future release") , reference : "issue #56105 <https://github.com/rust-lang/rust/issues/56105>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `deprecated` lint detects use of deprecated items."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #[deprecated]"] # [doc = " fn foo() {}"] # [doc = ""] # [doc = " fn bar() {"] # [doc = "     foo();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Items may be marked \"deprecated\" with the [`deprecated` attribute] to"] # [doc = " indicate that they should no longer be used. Usually the attribute"] # [doc = " should include a note on what to use instead, or check the"] # [doc = " documentation."] # [doc = ""] # [doc = " [`deprecated` attribute]: https://doc.rust-lang.org/reference/attributes/diagnostics.html#the-deprecated-attribute"] pub DEPRECATED , Warn , "detects use of deprecated items" , report_in_external_macro }}
