mkitem!{declare_lint ! { # [doc = " The `rust_2024_incompatible_pat` lint"] # [doc = " detects patterns whose meaning will change in the Rust 2024 edition."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2021"] # [doc = " #![warn(rust_2024_incompatible_pat)]"] # [doc = ""] # [doc = " if let Some(&a) = &Some(&0u8) {"] # [doc = "     let _: u8 = a;"] # [doc = " }"] # [doc = " if let Some(mut _a) = &mut Some(0u8) {"] # [doc = "     _a = 7u8;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In Rust 2024 and above, the `mut` keyword does not reset the pattern binding mode,"] # [doc = " and nor do `&` or `&mut` patterns. The lint will suggest code that"] # [doc = " has the same meaning in all editions."] pub RUST_2024_INCOMPATIBLE_PAT , Allow , "detects patterns whose meaning will change in Rust 2024" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/nightly/edition-guide/rust-2024/match-ergonomics.html>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `unconditional_recursion` lint detects functions that cannot"] # [doc = " return without calling themselves."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn foo() {"] # [doc = "     foo();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " It is usually a mistake to have a recursive call that does not have"] # [doc = " some condition to cause it to terminate. If you really intend to have"] # [doc = " an infinite loop, using a `loop` expression is recommended."] pub UNCONDITIONAL_RECURSION , Warn , "functions that cannot return without calling themselves" }}
mkitem!{declare_lint ! { # [doc = " The `single_use_lifetimes` lint detects lifetimes that are only used"] # [doc = " once."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(single_use_lifetimes)]"] # [doc = ""] # [doc = " fn foo<'a>(x: &'a u32) {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Specifying an explicit lifetime like `'a` in a function or `impl`"] # [doc = " should only be used to link together two things. Otherwise, you should"] # [doc = " just use `'_` to indicate that the lifetime is not linked to anything,"] # [doc = " or elide the lifetime altogether if possible."] # [doc = ""] # [doc = " This lint is \"allow\" by default because it was introduced at a time"] # [doc = " when `'_` and elided lifetimes were first being introduced, and this"] # [doc = " lint would be too noisy. Also, there are some known false positives"] # [doc = " that it produces. See [RFC 2115] for historical context, and [issue"] # [doc = " #44752] for more details."] # [doc = ""] # [doc = " [RFC 2115]: https://github.com/rust-lang/rfcs/blob/master/text/2115-argument-lifetimes.md"] # [doc = " [issue #44752]: https://github.com/rust-lang/rust/issues/44752"] pub SINGLE_USE_LIFETIMES , Allow , "detects lifetime parameters that are only used once" }}
