mkitem!{declare_lint ! { # [doc = " The `irrefutable_let_patterns` lint detects [irrefutable patterns]"] # [doc = " in [`if let`]s, [`while let`]s, and `if let` guards."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " if let _ = 123 {"] # [doc = "     println!(\"always runs!\");"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " There usually isn't a reason to have an irrefutable pattern in an"] # [doc = " `if let` or `while let` statement, because the pattern will always match"] # [doc = " successfully. A [`let`] or [`loop`] statement will suffice. However,"] # [doc = " when generating code with a macro, forbidding irrefutable patterns"] # [doc = " would require awkward workarounds in situations where the macro"] # [doc = " doesn't know if the pattern is refutable or not. This lint allows"] # [doc = " macros to accept this form, while alerting for a possibly incorrect"] # [doc = " use in normal code."] # [doc = ""] # [doc = " See [RFC 2086] for more details."] # [doc = ""] # [doc = " [irrefutable patterns]: https://doc.rust-lang.org/reference/patterns.html#refutability"] # [doc = " [`if let`]: https://doc.rust-lang.org/reference/expressions/if-expr.html#if-let-expressions"] # [doc = " [`while let`]: https://doc.rust-lang.org/reference/expressions/loop-expr.html#predicate-pattern-loops"] # [doc = " [`let`]: https://doc.rust-lang.org/reference/statements.html#let-statements"] # [doc = " [`loop`]: https://doc.rust-lang.org/reference/expressions/loop-expr.html#infinite-loops"] # [doc = " [RFC 2086]: https://github.com/rust-lang/rfcs/blob/master/text/2086-allow-if-let-irrefutables.md"] pub IRREFUTABLE_LET_PATTERNS , Warn , "detects irrefutable patterns in `if let` and `while let` statements" }}
