mkitem!{declare_lint ! { # [doc = " The `unsafe_op_in_unsafe_fn` lint detects unsafe operations in unsafe"] # [doc = " functions without an explicit unsafe block."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(unsafe_op_in_unsafe_fn)]"] # [doc = ""] # [doc = " unsafe fn foo() {}"] # [doc = ""] # [doc = " unsafe fn bar() {"] # [doc = "     foo();"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Currently, an [`unsafe fn`] allows any [unsafe] operation within its"] # [doc = " body. However, this can increase the surface area of code that needs"] # [doc = " to be scrutinized for proper behavior. The [`unsafe` block] provides a"] # [doc = " convenient way to make it clear exactly which parts of the code are"] # [doc = " performing unsafe operations. In the future, it is desired to change"] # [doc = " it so that unsafe operations cannot be performed in an `unsafe fn`"] # [doc = " without an `unsafe` block."] # [doc = ""] # [doc = " The fix to this is to wrap the unsafe code in an `unsafe` block."] # [doc = ""] # [doc = " This lint is \"allow\" by default on editions up to 2021, from 2024 it is"] # [doc = " \"warn\" by default; the plan for increasing severity further is"] # [doc = " still being considered. See [RFC #2585] and [issue #71668] for more"] # [doc = " details."] # [doc = ""] # [doc = " [`unsafe fn`]: https://doc.rust-lang.org/reference/unsafe-functions.html"] # [doc = " [`unsafe` block]: https://doc.rust-lang.org/reference/expressions/block-expr.html#unsafe-blocks"] # [doc = " [unsafe]: https://doc.rust-lang.org/reference/unsafety.html"] # [doc = " [RFC #2585]: https://github.com/rust-lang/rfcs/blob/master/text/2585-unsafe-block-in-unsafe-fn.md"] # [doc = " [issue #71668]: https://github.com/rust-lang/rust/issues/71668"] pub UNSAFE_OP_IN_UNSAFE_FN , Allow , "unsafe operations in unsafe functions without an explicit unsafe block are deprecated" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/unsafe-op-in-unsafe-fn.html>" , explain_reason : false } ; @ edition Edition2024 => Warn ; }}
mkitem!{declare_lint ! { # [doc = " The `fuzzy_provenance_casts` lint detects an `as` cast between an integer"] # [doc = " and a pointer."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(strict_provenance_lints)]"] # [doc = " #![warn(fuzzy_provenance_casts)]"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let _dangling = 16_usize as *const u8;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " This lint is part of the strict provenance effort, see [issue #95228]."] # [doc = " Casting an integer to a pointer is considered bad style, as a pointer"] # [doc = " contains, besides the *address* also a *provenance*, indicating what"] # [doc = " memory the pointer is allowed to read/write. Casting an integer, which"] # [doc = " doesn't have provenance, to a pointer requires the compiler to assign"] # [doc = " (guess) provenance. The compiler assigns \"all exposed valid\" (see the"] # [doc = " docs of [`ptr::with_exposed_provenance`] for more information about this"] # [doc = " \"exposing\"). This penalizes the optimiser and is not well suited for"] # [doc = " dynamic analysis/dynamic program verification (e.g. Miri or CHERI"] # [doc = " platforms)."] # [doc = ""] # [doc = " It is much better to use [`ptr::with_addr`] instead to specify the"] # [doc = " provenance you want. If using this function is not possible because the"] # [doc = " code relies on exposed provenance then there is as an escape hatch"] # [doc = " [`ptr::with_exposed_provenance`]."] # [doc = ""] # [doc = " [issue #95228]: https://github.com/rust-lang/rust/issues/95228"] # [doc = " [`ptr::with_addr`]: https://doc.rust-lang.org/core/primitive.pointer.html#method.with_addr"] # [doc = " [`ptr::with_exposed_provenance`]: https://doc.rust-lang.org/core/ptr/fn.with_exposed_provenance.html"] pub FUZZY_PROVENANCE_CASTS , Allow , "a fuzzy integer to pointer cast is used" , @ feature_gate = strict_provenance_lints ; }}
mkitem!{declare_lint ! { # [doc = " The `lossy_provenance_casts` lint detects an `as` cast between a pointer"] # [doc = " and an integer."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(strict_provenance_lints)]"] # [doc = " #![warn(lossy_provenance_casts)]"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let x: u8 = 37;"] # [doc = "     let _addr: usize = &x as *const u8 as usize;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " This lint is part of the strict provenance effort, see [issue #95228]."] # [doc = " Casting a pointer to an integer is a lossy operation, because beyond"] # [doc = " just an *address* a pointer may be associated with a particular"] # [doc = " *provenance*. This information is used by the optimiser and for dynamic"] # [doc = " analysis/dynamic program verification (e.g. Miri or CHERI platforms)."] # [doc = ""] # [doc = " Since this cast is lossy, it is considered good style to use the"] # [doc = " [`ptr::addr`] method instead, which has a similar effect, but doesn't"] # [doc = " \"expose\" the pointer provenance. This improves optimisation potential."] # [doc = " See the docs of [`ptr::addr`] and [`ptr::expose_provenance`] for more information"] # [doc = " about exposing pointer provenance."] # [doc = ""] # [doc = " If your code can't comply with strict provenance and needs to expose"] # [doc = " the provenance, then there is [`ptr::expose_provenance`] as an escape hatch,"] # [doc = " which preserves the behaviour of `as usize` casts while being explicit"] # [doc = " about the semantics."] # [doc = ""] # [doc = " [issue #95228]: https://github.com/rust-lang/rust/issues/95228"] # [doc = " [`ptr::addr`]: https://doc.rust-lang.org/core/primitive.pointer.html#method.addr"] # [doc = " [`ptr::expose_provenance`]: https://doc.rust-lang.org/core/primitive.pointer.html#method.expose_provenance"] pub LOSSY_PROVENANCE_CASTS , Allow , "a lossy pointer to integer cast is used" , @ feature_gate = strict_provenance_lints ; }}
mkitem!{declare_lint ! { # [doc = " The `const_evaluatable_unchecked` lint detects a generic constant used"] # [doc = " in a type."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " const fn foo<T>() -> usize {"] # [doc = "     if size_of::<*mut T>() < 8 { // size of *mut T does not depend on T"] # [doc = "         4"] # [doc = "     } else {"] # [doc = "         8"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " fn test<T>() {"] # [doc = "     let _ = [0; foo::<T>()];"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In the 1.43 release, some uses of generic parameters in array repeat"] # [doc = " expressions were accidentally allowed. This is a [future-incompatible]"] # [doc = " lint to transition this to a hard error in the future. See [issue"] # [doc = " #76200] for a more detailed description and possible fixes."] # [doc = ""] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] # [doc = " [issue #76200]: https://github.com/rust-lang/rust/issues/76200"] pub CONST_EVALUATABLE_UNCHECKED , Warn , "detects a generic constant is used in a type without a emitting a warning" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #76200 <https://github.com/rust-lang/rust/issues/76200>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `function_item_references` lint detects function references that are"] # [doc = " formatted with [`fmt::Pointer`] or transmuted."] # [doc = ""] # [doc = " [`fmt::Pointer`]: https://doc.rust-lang.org/std/fmt/trait.Pointer.html"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn foo() { }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     println!(\"{:p}\", &foo);"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Taking a reference to a function may be mistaken as a way to obtain a"] # [doc = " pointer to that function. This can give unexpected results when"] # [doc = " formatting the reference as a pointer or transmuting it. This lint is"] # [doc = " issued when function references are formatted as pointers, passed as"] # [doc = " arguments bound by [`fmt::Pointer`] or transmuted."] pub FUNCTION_ITEM_REFERENCES , Warn , "suggest casting to a function pointer when attempting to take references to function items" , }}
mkitem!{declare_lint ! { # [doc = " The `uninhabited_static` lint detects uninhabited statics."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " enum Void {}"] # [doc = " unsafe extern {"] # [doc = "     static EXTERN: Void;"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Statics with an uninhabited type can never be initialized, so they are impossible to define."] # [doc = " However, this can be side-stepped with an `extern static`, leading to problems later in the"] # [doc = " compiler which assumes that there are no initialized uninhabited places (such as locals or"] # [doc = " statics). This was accidentally allowed, but is being phased out."] pub UNINHABITED_STATIC , Warn , "uninhabited static" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #74840 <https://github.com/rust-lang/rust/issues/74840>" , } ; }}
