mkitem!{declare_lint ! { # [doc = " The `long_running_const_eval` lint is emitted when const"] # [doc = " eval is running for a long time to ensure rustc terminates"] # [doc = " even if you accidentally wrote an infinite loop."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " const FOO: () = loop {};"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Loops allow const evaluation to compute arbitrary code, but may also"] # [doc = " cause infinite loops or just very long running computations."] # [doc = " Users can enable long running computations by allowing the lint"] # [doc = " on individual constants or for entire crates."] # [doc = ""] # [doc = " ### Unconditional warnings"] # [doc = ""] # [doc = " Note that regardless of whether the lint is allowed or set to warn,"] # [doc = " the compiler will issue warnings if constant evaluation runs significantly"] # [doc = " longer than this lint's limit. These warnings are also shown to downstream"] # [doc = " users from crates.io or similar registries. If you are above the lint's limit,"] # [doc = " both you and downstream users might be exposed to these warnings."] # [doc = " They might also appear on compiler updates, as the compiler makes minor changes"] # [doc = " about how complexity is measured: staying below the limit ensures that there"] # [doc = " is enough room, and given that the lint is disabled for people who use your"] # [doc = " dependency it means you will be the only one to get the warning and can put"] # [doc = " out an update in your own time."] pub LONG_RUNNING_CONST_EVAL , Deny , "detects long const eval operations" , report_in_external_macro }}
