mkitem!{declare_lint ! { # [doc = " The `rust_2021_incompatible_closure_captures` lint detects variables that aren't completely"] # [doc = " captured in Rust 2021, such that the `Drop` order of their fields may differ between"] # [doc = " Rust 2018 and 2021."] # [doc = ""] # [doc = " It can also detect when a variable implements a trait like `Send`, but one of its fields does not,"] # [doc = " and the field is captured by a closure and used with the assumption that said field implements"] # [doc = " the same trait as the root variable."] # [doc = ""] # [doc = " ### Example of drop reorder"] # [doc = ""] # [doc = " ```rust,edition2018,compile_fail"] # [doc = " #![deny(rust_2021_incompatible_closure_captures)]"] # [doc = " # #![allow(unused)]"] # [doc = ""] # [doc = " struct FancyInteger(i32);"] # [doc = ""] # [doc = " impl Drop for FancyInteger {"] # [doc = "     fn drop(&mut self) {"] # [doc = "         println!(\"Just dropped {}\", self.0);"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " struct Point { x: FancyInteger, y: FancyInteger }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "   let p = Point { x: FancyInteger(10), y: FancyInteger(20) };"] # [doc = ""] # [doc = "   let c = || {"] # [doc = "      let x = p.x;"] # [doc = "   };"] # [doc = ""] # [doc = "   c();"] # [doc = ""] # [doc = "   // ... More code ..."] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In the above example, `p.y` will be dropped at the end of `f` instead of"] # [doc = " with `c` in Rust 2021."] # [doc = ""] # [doc = " ### Example of auto-trait"] # [doc = ""] # [doc = " ```rust,edition2018,compile_fail"] # [doc = " #![deny(rust_2021_incompatible_closure_captures)]"] # [doc = " use std::thread;"] # [doc = ""] # [doc = " struct Pointer(*mut i32);"] # [doc = " unsafe impl Send for Pointer {}"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     let mut f = 10;"] # [doc = "     let fptr = Pointer(&mut f as *mut i32);"] # [doc = "     thread::spawn(move || unsafe {"] # [doc = "         *fptr.0 = 20;"] # [doc = "     });"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In the above example, only `fptr.0` is captured in Rust 2021."] # [doc = " The field is of type `*mut i32`, which doesn't implement `Send`,"] # [doc = " making the code invalid as the field cannot be sent between threads safely."] pub RUST_2021_INCOMPATIBLE_CLOSURE_CAPTURES , Allow , "detects closures affected by Rust 2021 changes" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2021) , explain_reason : false , } ; }}
