mkitem!{declare_lint ! { # [doc = " The `rust_2021_prefixes_incompatible_syntax` lint detects identifiers that will be parsed as a"] # [doc = " prefix instead in Rust 2021."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2018,compile_fail"] # [doc = " #![deny(rust_2021_prefixes_incompatible_syntax)]"] # [doc = ""] # [doc = " macro_rules! m {"] # [doc = "     (z $x:expr) => ();"] # [doc = " }"] # [doc = ""] # [doc = " m!(z\"hey\");"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In Rust 2015 and 2018, `z\"hey\"` is two tokens: the identifier `z`"] # [doc = " followed by the string literal `\"hey\"`. In Rust 2021, the `z` is"] # [doc = " considered a prefix for `\"hey\"`."] # [doc = ""] # [doc = " This lint suggests to add whitespace between the `z` and `\"hey\"` tokens"] # [doc = " to keep them separated in Rust 2021."] # [allow (rustdoc :: invalid_rust_codeblocks)] pub RUST_2021_PREFIXES_INCOMPATIBLE_SYNTAX , Allow , "identifiers that will be parsed as a prefix in Rust 2021" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionError (Edition :: Edition2021) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2021/reserving-syntax.html>" , } ; crate_level_only }}
mkitem!{declare_lint ! { # [doc = " The `unsupported_calling_conventions` lint is output whenever there is a use of the"] # [doc = " `stdcall`, `fastcall`, and `cdecl` calling conventions (or their unwind"] # [doc = " variants) on targets that cannot meaningfully be supported for the requested target."] # [doc = ""] # [doc = " For example `stdcall` does not make much sense for a x86_64 or, more apparently, powerpc"] # [doc = " code, because this calling convention was never specified for those targets."] # [doc = ""] # [doc = " Historically MSVC toolchains have fallen back to the regular C calling convention for"] # [doc = " targets other than x86, but Rust doesn't really see a similar need to introduce a similar"] # [doc = " hack across many more targets."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs specific targets)"] # [doc = " extern \"stdcall\" fn stdcall() {}"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: use of calling convention not supported on this target"] # [doc = "   --> $DIR/unsupported.rs:39:1"] # [doc = "    |"] # [doc = " LL | extern \"stdcall\" fn stdcall() {}"] # [doc = "    | ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = "    |"] # [doc = "    = note: `#[warn(unsupported_calling_conventions)]` on by default"] # [doc = "    = warning: this was previously accepted by the compiler but is being phased out;"] # [doc = "               it will become a hard error in a future release!"] # [doc = "    = note: for more information, see issue ..."] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " On most of the targets the behaviour of `stdcall` and similar calling conventions is not"] # [doc = " defined at all, but was previously accepted due to a bug in the implementation of the"] # [doc = " compiler."] pub UNSUPPORTED_CALLING_CONVENTIONS , Warn , "use of unsupported calling convention" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , report_in_deps : false , reference : "issue #137018 <https://github.com/rust-lang/rust/issues/137018>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `unsupported_fn_ptr_calling_conventions` lint is output whenever there is a use of"] # [doc = " a target dependent calling convention on a target that does not support this calling"] # [doc = " convention on a function pointer."] # [doc = ""] # [doc = " For example `stdcall` does not make much sense for a x86_64 or, more apparently, powerpc"] # [doc = " code, because this calling convention was never specified for those targets."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs specific targets)"] # [doc = " fn stdcall_ptr(f: extern \"stdcall\" fn ()) {"] # [doc = "     f()"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: the calling convention `\"stdcall\"` is not supported on this target"] # [doc = "   --> $DIR/unsupported.rs:34:15"] # [doc = "    |"] # [doc = " LL | fn stdcall_ptr(f: extern \"stdcall\" fn()) {"] # [doc = "    |               ^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = "    |"] # [doc = "    = warning: this was previously accepted by the compiler but is being phased out; it will become a hard error in a future release!"] # [doc = "    = note: for more information, see issue #130260 <https://github.com/rust-lang/rust/issues/130260>"] # [doc = "    = note: `#[warn(unsupported_fn_ptr_calling_conventions)]` on by default"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " On most of the targets the behaviour of `stdcall` and similar calling conventions is not"] # [doc = " defined at all, but was previously accepted due to a bug in the implementation of the"] # [doc = " compiler."] pub UNSUPPORTED_FN_PTR_CALLING_CONVENTIONS , Warn , "use of unsupported calling convention for function pointer" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #130260 <https://github.com/rust-lang/rust/issues/130260>" , report_in_deps : true , } ; }}
mkitem!{declare_lint ! { # [doc = " The `break_with_label_and_loop` lint detects labeled `break` expressions with"] # [doc = " an unlabeled loop as their value expression."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " 'label: loop {"] # [doc = "     break 'label loop { break 42; };"] # [doc = " };"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In Rust, loops can have a label, and `break` expressions can refer to that label to"] # [doc = " break out of specific loops (and not necessarily the innermost one). `break` expressions"] # [doc = " can also carry a value expression, which can be another loop. A labeled `break` with an"] # [doc = " unlabeled loop as its value expression is easy to confuse with an unlabeled break with"] # [doc = " a labeled loop and is thus discouraged (but allowed for compatibility); use parentheses"] # [doc = " around the loop expression to silence this warning. Unlabeled `break` expressions with"] # [doc = " labeled loops yield a hard error, which can also be silenced by wrapping the expression"] # [doc = " in parentheses."] pub BREAK_WITH_LABEL_AND_LOOP , Warn , "`break` expression with label and unlabeled loop as value expression" }}
mkitem!{declare_lint ! { # [doc = " The `non_exhaustive_omitted_patterns` lint aims to help consumers of a `#[non_exhaustive]`"] # [doc = " struct or enum who want to match all of its fields/variants explicitly."] # [doc = ""] # [doc = " The `#[non_exhaustive]` annotation forces matches to use wildcards, so exhaustiveness"] # [doc = " checking cannot be used to ensure that all fields/variants are matched explicitly. To remedy"] # [doc = " this, this allow-by-default lint warns the user when a match mentions some but not all of"] # [doc = " the fields/variants of a `#[non_exhaustive]` struct or enum."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs separate crate)"] # [doc = " // crate A"] # [doc = " #[non_exhaustive]"] # [doc = " pub enum Bar {"] # [doc = "     A,"] # [doc = "     B, // added variant in non breaking change"] # [doc = " }"] # [doc = ""] # [doc = " // in crate B"] # [doc = " #![feature(non_exhaustive_omitted_patterns_lint)]"] # [doc = " #[warn(non_exhaustive_omitted_patterns)]"] # [doc = " match Bar::A {"] # [doc = "     Bar::A => {},"] # [doc = "     _ => {},"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: some variants are not matched explicitly"] # [doc = "    --> $DIR/reachable-patterns.rs:70:9"] # [doc = "    |"] # [doc = " LL |         match Bar::A {"] # [doc = "    |               ^ pattern `Bar::B` not covered"] # [doc = "    |"] # [doc = "  note: the lint level is defined here"] # [doc = "   --> $DIR/reachable-patterns.rs:69:16"] # [doc = "    |"] # [doc = " LL |         #[warn(non_exhaustive_omitted_patterns)]"] # [doc = "    |                ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = "    = help: ensure that all variants are matched explicitly by adding the suggested match arms"] # [doc = "    = note: the matched value is of type `Bar` and the `non_exhaustive_omitted_patterns` attribute was found"] # [doc = " ```"] # [doc = ""] # [doc = " Warning: setting this to `deny` will make upstream non-breaking changes (adding fields or"] # [doc = " variants to a `#[non_exhaustive]` struct or enum) break your crate. This goes against"] # [doc = " expected semver behavior."] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Structs and enums tagged with `#[non_exhaustive]` force the user to add a (potentially"] # [doc = " redundant) wildcard when pattern-matching, to allow for future addition of fields or"] # [doc = " variants. The `non_exhaustive_omitted_patterns` lint detects when such a wildcard happens to"] # [doc = " actually catch some fields/variants. In other words, when the match without the wildcard"] # [doc = " would not be exhaustive. This lets the user be informed if new fields/variants were added."] pub NON_EXHAUSTIVE_OMITTED_PATTERNS , Allow , "detect when patterns of types marked `non_exhaustive` are missed" , @ feature_gate = non_exhaustive_omitted_patterns_lint ; }}
mkitem!{declare_lint ! { # [doc = " The `text_direction_codepoint_in_comment` lint detects Unicode codepoints in comments that"] # [doc = " change the visual representation of text on screen in a way that does not correspond to"] # [doc = " their on memory representation."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(text_direction_codepoint_in_comment)]"] # [doc = " fn main() {"] # [doc = "    println!(\"{:?}\"); // '\u{202E}');"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Unicode allows changing the visual flow of text on screen in order to support scripts that"] # [doc = " are written right-to-left, but a specially crafted comment can make code that will be"] # [doc = " compiled appear to be part of a comment, depending on the software used to read the code."] # [doc = " To avoid potential problems or confusion, such as in CVE-2021-42574, by default we deny"] # [doc = " their use."] pub TEXT_DIRECTION_CODEPOINT_IN_COMMENT , Deny , "invisible directionality-changing codepoints in comment" , crate_level_only }}
mkitem!{declare_lint ! { # [doc = " The `text_direction_codepoint_in_literal` lint detects Unicode codepoints that change the"] # [doc = " visual representation of text on screen in a way that does not correspond to their on"] # [doc = " memory representation."] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The unicode characters `\\u{202A}`, `\\u{202B}`, `\\u{202D}`, `\\u{202E}`, `\\u{2066}`,"] # [doc = " `\\u{2067}`, `\\u{2068}`, `\\u{202C}` and `\\u{2069}` make the flow of text on screen change"] # [doc = " its direction on software that supports these codepoints. This makes the text \"abc\" display"] # [doc = " as \"cba\" on screen. By leveraging software that supports these, people can write specially"] # [doc = " crafted literals that make the surrounding code seem like it's performing one action, when"] # [doc = " in reality it is performing another. Because of this, we proactively lint against their"] # [doc = " presence to avoid surprises."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(text_direction_codepoint_in_literal)]"] # [doc = " fn main() {"] # [doc = "    println!(\"{:?}\", '\u{202E}');"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] pub TEXT_DIRECTION_CODEPOINT_IN_LITERAL , Deny , "detect special Unicode codepoints that affect the visual representation of text on screen, \
     changing the direction in which text flows" , crate_level_only }}
