mkitem!{declare_lint ! { # [doc = " The `deprecated_where_clause_location` lint detects when a where clause in front of the equals"] # [doc = " in an associated type."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " trait Trait {"] # [doc = "   type Assoc<'a> where Self: 'a;"] # [doc = " }"] # [doc = ""] # [doc = " impl Trait for () {"] # [doc = "   type Assoc<'a> where Self: 'a = ();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The preferred location for where clauses on associated types"] # [doc = " is after the type. However, for most of generic associated types development,"] # [doc = " it was only accepted before the equals. To provide a transition period and"] # [doc = " further evaluate this change, both are currently accepted. At some point in"] # [doc = " the future, this may be disallowed at an edition boundary; but, that is"] # [doc = " undecided currently."] pub DEPRECATED_WHERE_CLAUSE_LOCATION , Warn , "deprecated where clause location" }}
mkitem!{declare_lint ! { # [doc = " The `test_unstable_lint` lint tests unstable lints and is perma-unstable."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " // This lint is intentionally used to test the compiler's behavior"] # [doc = " // when an unstable lint is enabled without the corresponding feature gate."] # [doc = " #![allow(test_unstable_lint)]"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In order to test the behavior of unstable lints, a permanently-unstable"] # [doc = " lint is required. This lint can be used to trigger warnings and errors"] # [doc = " from the compiler related to unstable lints."] pub TEST_UNSTABLE_LINT , Deny , "this unstable lint is only for testing" , @ feature_gate = test_unstable_lint ; }}
mkitem!{declare_lint ! { # [doc = " The `ffi_unwind_calls` lint detects calls to foreign functions or function pointers with"] # [doc = " `C-unwind` or other FFI-unwind ABIs."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![warn(ffi_unwind_calls)]"] # [doc = ""] # [doc = " unsafe extern \"C-unwind\" {"] # [doc = "     fn foo();"] # [doc = " }"] # [doc = ""] # [doc = " fn bar() {"] # [doc = "     unsafe { foo(); }"] # [doc = "     let ptr: unsafe extern \"C-unwind\" fn() = foo;"] # [doc = "     unsafe { ptr(); }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " For crates containing such calls, if they are compiled with `-C panic=unwind` then the"] # [doc = " produced library cannot be linked with crates compiled with `-C panic=abort`. For crates"] # [doc = " that desire this ability it is therefore necessary to avoid such calls."] pub FFI_UNWIND_CALLS , Allow , "call to foreign functions or function pointers with FFI-unwind ABI" }}
mkitem!{declare_lint ! { # [doc = " The `linker_messages` lint forwards warnings from the linker."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs CLI args, platform-specific)"] # [doc = " #[warn(linker_messages)]"] # [doc = " extern \"C\" {"] # [doc = "   fn foo();"] # [doc = " }"] # [doc = " fn main () { unsafe { foo(); } }"] # [doc = " ```"] # [doc = ""] # [doc = " On Linux, using `gcc -Wl,--warn-unresolved-symbols` as a linker, this will produce"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: linker stderr: rust-lld: undefined symbol: foo"] # [doc = "          >>> referenced by rust_out.69edbd30df4ae57d-cgu.0"] # [doc = "          >>>               rust_out.rust_out.69edbd30df4ae57d-cgu.0.rcgu.o:(rust_out::main::h3a90094b06757803)"] # [doc = "   |"] # [doc = " note: the lint level is defined here"] # [doc = "  --> warn.rs:1:9"] # [doc = "   |"] # [doc = " 1 | #![warn(linker_messages)]"] # [doc = "   |         ^^^^^^^^^^^^^^^"] # [doc = " warning: 1 warning emitted"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Linkers emit platform-specific and program-specific warnings that cannot be predicted in"] # [doc = " advance by the Rust compiler. Such messages are ignored by default for now. While linker"] # [doc = " warnings could be very useful they have been ignored for many years by essentially all"] # [doc = " users, so we need to do a bit more work than just surfacing their text to produce a clear"] # [doc = " and actionable warning of similar quality to our other diagnostics. See this tracking"] # [doc = " issue for more details: <https://github.com/rust-lang/rust/issues/136096>."] pub LINKER_MESSAGES , Allow , "warnings emitted at runtime by the target-specific linker program" }}
mkitem!{declare_lint ! { # [doc = " The `named_arguments_used_positionally` lint detects cases where named arguments are only"] # [doc = " used positionally in format strings. This usage is valid but potentially very confusing."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(named_arguments_used_positionally)]"] # [doc = " fn main() {"] # [doc = "     let _x = 5;"] # [doc = "     println!(\"{}\", _x = 1); // Prints 1, will trigger lint"] # [doc = ""] # [doc = "     println!(\"{}\", _x); // Prints 5, no lint emitted"] # [doc = "     println!(\"{_x}\", _x = _x); // Prints 5, no lint emitted"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Rust formatting strings can refer to named arguments by their position, but this usage is"] # [doc = " potentially confusing. In particular, readers can incorrectly assume that the declaration"] # [doc = " of named arguments is an assignment (which would produce the unit type)."] # [doc = " For backwards compatibility, this is not a hard error."] pub NAMED_ARGUMENTS_USED_POSITIONALLY , Warn , "named arguments in format used positionally" }}
mkitem!{declare_lint ! { # [doc = " The `never_type_fallback_flowing_into_unsafe` lint detects cases where never type fallback"] # [doc = " affects unsafe function calls."] # [doc = ""] # [doc = " ### Never type fallback"] # [doc = ""] # [doc = " When the compiler sees a value of type [`!`] it implicitly inserts a coercion (if possible),"] # [doc = " to allow type check to infer any type:"] # [doc = ""] # [doc = " ```ignore (illustrative-and-has-placeholders)"] # [doc = " // this"] # [doc = " let x: u8 = panic!();"] # [doc = ""] # [doc = " // is (essentially) turned by the compiler into"] # [doc = " let x: u8 = absurd(panic!());"] # [doc = ""] # [doc = " // where absurd is a function with the following signature"] # [doc = " // (it's sound, because `!` always marks unreachable code):"] # [doc = " fn absurd<T>(never: !) -> T { ... }"] # [doc = " ```"] # [doc = ""] # [doc = " While it's convenient to be able to use non-diverging code in one of the branches (like"] # [doc = " `if a { b } else { return }`) this could lead to compilation errors:"] # [doc = ""] # [doc = " ```compile_fail"] # [doc = " // this"] # [doc = " { panic!() };"] # [doc = ""] # [doc = " // gets turned into this"] # [doc = " { absurd(panic!()) }; // error: can't infer the type of `absurd`"] # [doc = " ```"] # [doc = ""] # [doc = " To prevent such errors, compiler remembers where it inserted `absurd` calls, and if it"] # [doc = " can't infer their type, it sets the type to fallback. `{ absurd::<Fallback>(panic!()) };`."] # [doc = " This is what is known as \"never type fallback\"."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![deny(never_type_fallback_flowing_into_unsafe)]"] # [doc = " fn main() {"] # [doc = "     if true {"] # [doc = "         // return has type `!` which, is some cases, causes never type fallback"] # [doc = "         return"] # [doc = "     } else {"] # [doc = "         // `zeroed` is an unsafe function, which returns an unbounded type"] # [doc = "         unsafe { std::mem::zeroed() }"] # [doc = "     };"] # [doc = "     // depending on the fallback, `zeroed` may create `()` (which is completely sound),"] # [doc = "     // or `!` (which is instant undefined behavior)"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Due to historic reasons never type fallback was `()`, meaning that `!` got spontaneously"] # [doc = " coerced to `()`. There are plans to change that, but they may make the code such as above"] # [doc = " unsound. Instead of depending on the fallback, you should specify the type explicitly:"] # [doc = " ```"] # [doc = " if true {"] # [doc = "     return"] # [doc = " } else {"] # [doc = "     // type is explicitly specified, fallback can't hurt us no more"] # [doc = "     unsafe { std::mem::zeroed::<()>() }"] # [doc = " };"] # [doc = " ```"] # [doc = ""] # [doc = " See [Tracking Issue for making `!` fall back to `!`](https://github.com/rust-lang/rust/issues/123748)."] # [doc = ""] # [doc = " [`!`]: https://doc.rust-lang.org/core/primitive.never.html"] # [doc = " [`()`]: https://doc.rust-lang.org/core/primitive.unit.html"] pub NEVER_TYPE_FALLBACK_FLOWING_INTO_UNSAFE , Warn , "never type fallback affecting unsafe function calls" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionAndFutureReleaseSemanticsChange (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/never-type-fallback.html>" , report_in_deps : true , } ; @ edition Edition2024 => Deny ; report_in_external_macro }}
mkitem!{declare_lint ! { # [doc = " The `dependency_on_unit_never_type_fallback` lint detects cases where code compiles with"] # [doc = " [never type fallback] being [`()`], but will stop compiling with fallback being [`!`]."] # [doc = ""] # [doc = " [never type fallback]: https://doc.rust-lang.org/nightly/core/primitive.never.html#never-type-fallback"] # [doc = " [`!`]: https://doc.rust-lang.org/core/primitive.never.html"] # [doc = " [`()`]: https://doc.rust-lang.org/core/primitive.unit.html"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail,edition2021"] # [doc = " #![deny(dependency_on_unit_never_type_fallback)]"] # [doc = " fn main() {"] # [doc = "     if true {"] # [doc = "         // return has type `!` which, is some cases, causes never type fallback"] # [doc = "         return"] # [doc = "     } else {"] # [doc = "         // the type produced by this call is not specified explicitly,"] # [doc = "         // so it will be inferred from the previous branch"] # [doc = "         Default::default()"] # [doc = "     };"] # [doc = "     // depending on the fallback, this may compile (because `()` implements `Default`),"] # [doc = "     // or it may not (because `!` does not implement `Default`)"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Due to historic reasons never type fallback was `()`, meaning that `!` got spontaneously"] # [doc = " coerced to `()`. There are plans to change that, but they may make the code such as above"] # [doc = " not compile. Instead of depending on the fallback, you should specify the type explicitly:"] # [doc = " ```"] # [doc = " if true {"] # [doc = "     return"] # [doc = " } else {"] # [doc = "     // type is explicitly specified, fallback can't hurt us no more"] # [doc = "     <() as Default>::default()"] # [doc = " };"] # [doc = " ```"] # [doc = ""] # [doc = " See [Tracking Issue for making `!` fall back to `!`](https://github.com/rust-lang/rust/issues/123748)."] pub DEPENDENCY_ON_UNIT_NEVER_TYPE_FALLBACK , Warn , "never type fallback affecting unsafe function calls" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionAndFutureReleaseError (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/never-type-fallback.html>" , report_in_deps : true , } ; report_in_external_macro }}
