mkitem!{declare_lint ! { # [doc = " The `uncovered_param_in_projection` lint detects a violation of one of Rust's orphan rules for"] # [doc = " foreign trait implementations that concerns the use of type parameters inside trait associated"] # [doc = " type paths (\"projections\") whose output may not be a local type that is mistakenly considered"] # [doc = " to \"cover\" said parameters which is **unsound** and which may be rejected by a future version"] # [doc = " of the compiler."] # [doc = ""] # [doc = " Originally reported in [#99554]."] # [doc = ""] # [doc = " [#99554]: https://github.com/rust-lang/rust/issues/99554"] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (dependent)"] # [doc = " // dependency.rs"] # [doc = " #![crate_type = \"lib\"]"] # [doc = ""] # [doc = " pub trait Trait<T, U> {}"] # [doc = " ```"] # [doc = ""] # [doc = " ```edition2021,ignore (needs dependency)"] # [doc = " // dependent.rs"] # [doc = " trait Identity {"] # [doc = "     type Output;"] # [doc = " }"] # [doc = ""] # [doc = " impl<T> Identity for T {"] # [doc = "     type Output = T;"] # [doc = " }"] # [doc = ""] # [doc = " struct Local;"] # [doc = ""] # [doc = " impl<T> dependency::Trait<Local, T> for <T as Identity>::Output {}"] # [doc = ""] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning[E0210]: type parameter `T` must be covered by another type when it appears before the first local type (`Local`)"] # [doc = "   --> dependent.rs:11:6"] # [doc = "    |"] # [doc = " 11 | impl<T> dependency::Trait<Local, T> for <T as Identity>::Output {}"] # [doc = "    |      ^ type parameter `T` must be covered by another type when it appears before the first local type (`Local`)"] # [doc = "    |"] # [doc = "    = warning: this was previously accepted by the compiler but is being phased out; it will become a hard error in a future release!"] # [doc = "    = note: for more information, see issue #124559 <https://github.com/rust-lang/rust/issues/124559>"] # [doc = "    = note: implementing a foreign trait is only possible if at least one of the types for which it is implemented is local, and no uncovered type parameters appear before that first local type"] # [doc = "    = note: in this case, 'before' refers to the following order: `impl<..> ForeignTrait<T1, ..., Tn> for T0`, where `T0` is the first and `Tn` is the last"] # [doc = "    = note: `#[warn(uncovered_param_in_projection)]` on by default"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " FIXME(fmease): Write explainer."] pub UNCOVERED_PARAM_IN_PROJECTION , Warn , "impl contains type parameters that are not covered" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #124559 <https://github.com/rust-lang/rust/issues/124559>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `deprecated_safe_2024` lint detects unsafe functions being used as"] # [doc = " safe functions."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2021,compile_fail"] # [doc = " #![deny(deprecated_safe)]"] # [doc = " // edition 2021"] # [doc = " use std::env;"] # [doc = " fn enable_backtrace() {"] # [doc = "     env::set_var(\"RUST_BACKTRACE\", \"1\");"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Rust [editions] allow the language to evolve without breaking backward"] # [doc = " compatibility. This lint catches code that uses `unsafe` functions that"] # [doc = " were declared as safe (non-`unsafe`) in editions prior to Rust 2024. If"] # [doc = " you switch the compiler to Rust 2024 without updating the code, then it"] # [doc = " will fail to compile if you are using a function previously marked as"] # [doc = " safe."] # [doc = ""] # [doc = " You can audit the code to see if it suffices the preconditions of the"] # [doc = " `unsafe` code, and if it does, you can wrap it in an `unsafe` block. If"] # [doc = " you can't fulfill the preconditions, you probably need to switch to a"] # [doc = " different way of doing what you want to achieve."] # [doc = ""] # [doc = " This lint can automatically wrap the calls in `unsafe` blocks, but this"] # [doc = " obviously cannot verify that the preconditions of the `unsafe`"] # [doc = " functions are fulfilled, so that is still up to the user."] # [doc = ""] # [doc = " The lint is currently \"allow\" by default, but that might change in the"] # [doc = " future."] # [doc = ""] # [doc = " [editions]: https://doc.rust-lang.org/edition-guide/"] pub DEPRECATED_SAFE_2024 , Allow , "detects unsafe functions being used as safe functions" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionError (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/newly-unsafe-functions.html>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `missing_unsafe_on_extern` lint detects missing unsafe keyword on extern declarations."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2021"] # [doc = " #![warn(missing_unsafe_on_extern)]"] # [doc = " #![allow(dead_code)]"] # [doc = ""] # [doc = " extern \"C\" {"] # [doc = "     fn foo(_: i32);"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {}"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Declaring extern items, even without ever using them, can cause Undefined Behavior. We"] # [doc = " should consider all sources of Undefined Behavior to be unsafe."] # [doc = ""] # [doc = " This is a [future-incompatible] lint to transition this to a"] # [doc = " hard error in the future."] # [doc = ""] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub MISSING_UNSAFE_ON_EXTERN , Allow , "detects missing unsafe keyword on extern declarations" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionError (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/unsafe-extern.html>" , } ; }}
