mkitem!{declare_lint ! { # [doc = " The `out_of_scope_macro_calls` lint detects `macro_rules` called when they are not in scope,"] # [doc = " above their definition, which may happen in key-value attributes."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [cfg_attr (not (bootstrap) , doc = "```rust,compile_fail")] # [cfg_attr (bootstrap , doc = "```rust")] # [doc = " #![doc = in_root!()]"] # [doc = ""] # [doc = " macro_rules! in_root { () => { \"\" } }"] # [doc = ""] # [doc = " fn main() {}"] # [cfg_attr (not (bootstrap) , doc = "```")] # [cfg_attr (bootstrap , doc = "```")] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " The scope in which a `macro_rules` item is visible starts at that item and continues"] # [doc = " below it. This is more similar to `let` than to other items, which are in scope both above"] # [doc = " and below their definition."] # [doc = " Due to a bug `macro_rules` were accidentally in scope inside some key-value attributes"] # [doc = " above their definition. The lint catches such cases."] # [doc = " To address the issue turn the `macro_rules` into a regularly scoped item by importing it"] # [doc = " with `use`."] # [doc = ""] # [doc = " This is a [future-incompatible] lint to transition this to a"] # [doc = " hard error in the future."] # [doc = ""] # [doc = " [future-incompatible]: ../index.md#future-incompatible-lints"] pub OUT_OF_SCOPE_MACRO_CALLS , Deny , "detects out of scope calls to `macro_rules` in key-value attributes" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #124535 <https://github.com/rust-lang/rust/issues/124535>" , report_in_deps : true , } ; }}
mkitem!{declare_lint ! { # [doc = " The `supertrait_item_shadowing_usage` lint detects when the"] # [doc = " usage of an item that is provided by both a subtrait and supertrait"] # [doc = " is shadowed, preferring the subtrait."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " #![feature(supertrait_item_shadowing)]"] # [doc = " #![deny(supertrait_item_shadowing_usage)]"] # [doc = ""] # [doc = " trait Upstream {"] # [doc = "     fn hello(&self) {}"] # [doc = " }"] # [doc = " impl<T> Upstream for T {}"] # [doc = ""] # [doc = " trait Downstream: Upstream {"] # [doc = "     fn hello(&self) {}"] # [doc = " }"] # [doc = " impl<T> Downstream for T {}"] # [doc = ""] # [doc = " struct MyType;"] # [doc = " MyType.hello();"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " RFC 3624 specified a heuristic in which a supertrait item would be"] # [doc = " shadowed by a subtrait item when ambiguity occurs during item"] # [doc = " selection. In order to mitigate side-effects of this happening"] # [doc = " silently, this lint detects these cases when users want to deny them"] # [doc = " or fix the call sites."] pub SUPERTRAIT_ITEM_SHADOWING_USAGE , Allow , "detects when a supertrait item is shadowed by a subtrait item" , @ feature_gate = supertrait_item_shadowing ; }}
