mkitem!{declare_lint ! { # [doc = " The `tail_expr_drop_order` lint looks for those values generated at the tail expression location,"] # [doc = " that runs a custom `Drop` destructor."] # [doc = " Some of them may be dropped earlier in Edition 2024 that they used to in Edition 2021 and prior."] # [doc = " This lint detects those cases and provides you information on those values and their custom destructor implementations."] # [doc = " Your discretion on this information is required."] # [doc = ""] # [doc = " ### Example"] # [doc = " ```rust,edition2021"] # [doc = " #![warn(tail_expr_drop_order)]"] # [doc = " struct Droppy(i32);"] # [doc = " impl Droppy {"] # [doc = "     fn get(&self) -> i32 {"] # [doc = "         self.0"] # [doc = "     }"] # [doc = " }"] # [doc = " impl Drop for Droppy {"] # [doc = "     fn drop(&mut self) {"] # [doc = "         // This is a custom destructor and it induces side-effects that is observable"] # [doc = "         // especially when the drop order at a tail expression changes."] # [doc = "         println!(\"loud drop {}\", self.0);"] # [doc = "     }"] # [doc = " }"] # [doc = " fn edition_2021() -> i32 {"] # [doc = "     let another_droppy = Droppy(0);"] # [doc = "     Droppy(1).get()"] # [doc = " }"] # [doc = " fn main() {"] # [doc = "     edition_2021();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " In tail expression of blocks or function bodies,"] # [doc = " values of type with significant `Drop` implementation has an ill-specified drop order"] # [doc = " before Edition 2024 so that they are dropped only after dropping local variables."] # [doc = " Edition 2024 introduces a new rule with drop orders for them,"] # [doc = " so that they are dropped first before dropping local variables."] # [doc = ""] # [doc = " A significant `Drop::drop` destructor here refers to an explicit, arbitrary"] # [doc = " implementation of the `Drop` trait on the type, with exceptions including `Vec`,"] # [doc = " `Box`, `Rc`, `BTreeMap` and `HashMap` that are marked by the compiler otherwise"] # [doc = " so long that the generic types have no significant destructor recursively."] # [doc = " In other words, a type has a significant drop destructor when it has a `Drop` implementation"] # [doc = " or its destructor invokes a significant destructor on a type."] # [doc = " Since we cannot completely reason about the change by just inspecting the existence of"] # [doc = " a significant destructor, this lint remains only a suggestion and is set to `allow` by default."] # [doc = ""] # [doc = " This lint only points out the issue with `Droppy`, which will be dropped before `another_droppy`"] # [doc = " does in Edition 2024."] # [doc = " No fix will be proposed by this lint."] # [doc = " However, the most probable fix is to hoist `Droppy` into its own local variable binding."] # [doc = " ```rust"] # [doc = " struct Droppy(i32);"] # [doc = " impl Droppy {"] # [doc = "     fn get(&self) -> i32 {"] # [doc = "         self.0"] # [doc = "     }"] # [doc = " }"] # [doc = " fn edition_2024() -> i32 {"] # [doc = "     let value = Droppy(0);"] # [doc = "     let another_droppy = Droppy(1);"] # [doc = "     value.get()"] # [doc = " }"] # [doc = " ```"] pub TAIL_EXPR_DROP_ORDER , Allow , "Detect and warn on significant change in drop order in tail expression location" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/temporary-tail-expr-scope.html>" , } ; }}
mkitem!{declare_lint ! { # [doc = " The `rust_2024_guarded_string_incompatible_syntax` lint detects `#` tokens"] # [doc = " that will be parsed as part of a guarded string literal in Rust 2024."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,edition2021,compile_fail"] # [doc = " #![deny(rust_2024_guarded_string_incompatible_syntax)]"] # [doc = ""] # [doc = " macro_rules! m {"] # [doc = "     (# $x:expr #) => ();"] # [doc = "     (# $x:expr) => ();"] # [doc = " }"] # [doc = ""] # [doc = " m!(#\"hey\"#);"] # [doc = " m!(#\"hello\");"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Prior to Rust 2024, `#\"hey\"#` is three tokens: the first `#`"] # [doc = " followed by the string literal `\"hey\"` then the final `#`."] # [doc = " In Rust 2024, the whole sequence is considered a single token."] # [doc = ""] # [doc = " This lint suggests to add whitespace between the leading `#`"] # [doc = " and the string to keep them separated in Rust 2024."] # [allow (rustdoc :: invalid_rust_codeblocks)] pub RUST_2024_GUARDED_STRING_INCOMPATIBLE_SYNTAX , Allow , "will be parsed as a guarded string in Rust 2024" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionError (Edition :: Edition2024) , reference : "<https://doc.rust-lang.org/edition-guide/rust-2024/reserved-syntax.html>" , } ; crate_level_only }}
mkitem!{declare_lint ! { # [doc = " The `aarch64_softfloat_neon` lint detects usage of `#[target_feature(enable = \"neon\")]` on"] # [doc = " softfloat aarch64 targets. Enabling this target feature causes LLVM to alter the ABI of"] # [doc = " function calls, making this attribute unsound to use."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (needs aarch64-unknown-none-softfloat)"] # [doc = " #[target_feature(enable = \"neon\")]"] # [doc = " fn with_neon() {}"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " error: enabling the `neon` target feature on the current target is unsound due to ABI issues"] # [doc = "   --> $DIR/abi-incompatible-target-feature-attribute-fcw.rs:11:18"] # [doc = "    |"] # [doc = "    | #[target_feature(enable = \"neon\")]"] # [doc = "    |                  ^^^^^^^^^^^^^^^"] # [doc = "    |"] # [doc = "    = warning: this was previously accepted by the compiler but is being phased out; it will become a hard error in a future release!"] # [doc = "    = note: for more information, see issue #134375 <https://github.com/rust-lang/rust/issues/134375>"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " If a function like `with_neon` above ends up containing calls to LLVM builtins, those will"] # [doc = " not use the correct ABI. This is caused by a lack of support in LLVM for mixing code with"] # [doc = " and without the `neon` target feature. The target feature should never have been stabilized"] # [doc = " on this target due to this issue, but the problem was not known at the time of"] # [doc = " stabilization."] pub AARCH64_SOFTFLOAT_NEON , Warn , "detects code that could be affected by ABI issues on aarch64 softfloat targets" , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: FutureReleaseError , reference : "issue #134375 <https://github.com/rust-lang/rust/issues/134375>" , report_in_deps : true , } ; }}
mkitem!{declare_lint ! { # [doc = " The `tail_call_track_caller` lint detects usage of `become` attempting to tail call"] # [doc = " a function marked with `#[track_caller]`."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![feature(explicit_tail_calls)]"] # [doc = " #![expect(incomplete_features)]"] # [doc = ""] # [doc = " #[track_caller]"] # [doc = " fn f() {}"] # [doc = ""] # [doc = " fn g() {"] # [doc = "     become f();"] # [doc = " }"] # [doc = ""] # [doc = " g();"] # [doc = " ```"] # [doc = ""] # [doc = " {{produces}}"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Due to implementation details of tail calls and `#[track_caller]` attribute, calls to"] # [doc = " functions marked with `#[track_caller]` cannot become tail calls. As such using `become`"] # [doc = " is no different than a normal call (except for changes in drop order)."] pub TAIL_CALL_TRACK_CALLER , Warn , "detects tail calls of functions marked with `#[track_caller]`" , @ feature_gate = explicit_tail_calls ; }}
mkitem!{declare_lint ! { # [doc = " The `inline_always_mismatching_target_features` lint will trigger when a"] # [doc = " function with the `#[inline(always)]` and `#[target_feature(enable = \"...\")]`"] # [doc = " attributes is called and cannot be inlined due to missing target features in the caller."] # [doc = ""] # [doc = " ### Example"] # [doc = ""] # [doc = " ```rust,ignore (fails on x86_64)"] # [doc = " #[inline(always)]"] # [doc = " #[target_feature(enable = \"fp16\")]"] # [doc = " unsafe fn callee() {"] # [doc = "     // operations using fp16 types"] # [doc = " }"] # [doc = ""] # [doc = " // Caller does not enable the required target feature"] # [doc = " fn caller() {"] # [doc = "     unsafe { callee(); }"] # [doc = " }"] # [doc = ""] # [doc = " fn main() {"] # [doc = "     caller();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " This will produce:"] # [doc = ""] # [doc = " ```text"] # [doc = " warning: call to `#[inline(always)]`-annotated `callee` requires the same target features. Function will not have `alwaysinline` attribute applied"] # [doc = "   --> $DIR/builtin.rs:5192:14"] # [doc = "    |"] # [doc = " 10 |     unsafe { callee(); }"] # [doc = "    |              ^^^^^^^^"] # [doc = "    |"] # [doc = " note: `fp16` target feature enabled in `callee` here but missing from `caller`"] # [doc = "   --> $DIR/builtin.rs:5185:1"] # [doc = "    |"] # [doc = " 3  | #[target_feature(enable = \"fp16\")]"] # [doc = "    | ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^"] # [doc = " 4  | unsafe fn callee() {"] # [doc = "    | ------------------"] # [doc = "    = note: `#[warn(inline_always_mismatching_target_features)]` on by default"] # [doc = " warning: 1 warning emitted"] # [doc = " ```"] # [doc = ""] # [doc = " ### Explanation"] # [doc = ""] # [doc = " Inlining a function with a target feature attribute into a caller that"] # [doc = " lacks the corresponding target feature can lead to unsound behavior."] # [doc = " LLVM may select the wrong instructions or registers, or reorder"] # [doc = " operations, potentially resulting in runtime errors."] pub INLINE_ALWAYS_MISMATCHING_TARGET_FEATURES , Warn , r#"detects when a function annotated with `#[inline(always)]` and `#[target_feature(enable = "..")]` is inlined into a caller without the required target feature"# , }}
